// Shared-initialization research comparison, no result caching; not final timing.
#include "core_template_model.hpp"
#include "buffered_csv_reader.hpp"
#include "buffered_csv_writer.hpp"
#include <filesystem>
#include <ctime>
std::string_view trim135(std::string_view s){auto a=s.find_first_not_of(" \r\n\t"),b=s.find_last_not_of(" \r\n\t");return a==s.npos?std::string_view{}:s.substr(a,b-a+1);}
int main(int argc,char**argv){try{if(argc!=4)throw std::runtime_error("asset folder, request file, output folder required");auto folder=std::filesystem::path(argv[1]);auto file=[&](const char*n){return (folder/n).string();};auto start=std::clock();Graph graph;CoreTemplateModel model(file("core-template.bin"),false,0,0,file("vertical-transients.bin"),UINT_MAX,file("horizontal-transients.bin"),file("vertical-far-delta.bin"),true,file("joint-interaction.bin"));model.enable_joint_layout();model.enable_short_vertical_layout();model.enable_corridor_hubs(1);model.enable_horizontal_layout();model.enable_terminal_hints(1,true);model.enable_horizontal_hints();model.enable_adaptive_sources(36);model.enable_source_hints(graph,8);
#if CORE_PHYSICAL_PORTALS
model.enable_physical_portals("out/v140/portal.raw.bin");
#endif
double init=double(std::clock()-start)/CLOCKS_PER_SEC;std::cerr<<"init="<<init<<'\n';FastPinParser parser;parser.enable_scan_coordinates();parser.enable_packed_port_index();struct Q{Node s,t;std::string from,to;};std::vector<Q>requests;BufferedCsvReader reader(argv[2]);std::string_view line;if(!reader.next(line)||trim135(line)!="From,To")throw std::runtime_error("header");while(reader.next(line)){line=trim135(line);if(line.empty())continue;auto c=line.find(',');if(c==line.npos)throw std::runtime_error("row");auto a=trim135(line.substr(0,c)),b=trim135(line.substr(c+1));requests.push_back({parser.pin(a),parser.pin(b),std::string(a),std::string(b)});}std::filesystem::create_directories(argv[3]);
model.enable_adaptive_sources(10000);std::ofstream f(std::filesystem::path(argv[3])/"branches.csv");std::vector<CoreTemplateModel::BranchSummary>branches;branches.reserve(32);for(const auto&q:requests){branches.clear();CoreTemplateModel::RouteTrace best;auto value=model.predict(graph,q.s,q.t,&best,nullptr,true,&branches);std::sort(branches.begin(),branches.end(),[](auto&a,auto&b){return a.delay<b.delay;});f<<value<<','<<branches.size();for(unsigned k=0;k<4;++k){if(k<branches.size()){auto&t=branches[k].trace;f<<','<<branches[k].delay<<','<<t.source_core<<','<<t.target_core<<','<<t.kind<<','<<t.entry_cost<<','<<t.source_x<<','<<t.source_y<<','<<t.qx<<','<<t.qy<<','<<t.rx<<','<<t.ry<<','<<t.base0<<','<<t.base1<<','<<t.base2<<','<<t.base3<<','<<t.horizontal_delta<<','<<t.interaction_delta;}else for(unsigned j=0;j<17;++j)f<<",-1";}f<<'\n';}if(!f)throw std::runtime_error("Branch write");std::cerr<<"rows="<<requests.size()<<'\n';}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
